style.css:
/* Body Styles */
body {
    background-color: #F5EFE7; /* Soft beige-themed background */
    color: #131313; /* Black text for readability */
    margin: 0;
    padding: 0;
}

/* Header Styles */
header {
    background: #E6D5B8; /* Fallback solid color */
    background: linear-gradient(90deg, #E6D5B8, #F5EFE7); /* Subtle gradient for elegance */
    color: #131313; /* Black text for contrast */
    text-align: center;
    padding: 20px 0;
    border-bottom: 3px solid #131313; /* Black border for sophistication */
}

/* Navigation Bar */
nav {
    background-color: #E6D5B8; /* Subtle gold tone */
    padding: 10px 20px;
    border-bottom: 2px solid #131313; /* Black border for separation */
}

nav a {
    color: #131313; /* Black links for simplicity */
    text-decoration: none;
    padding: 10px 15px;
    margin: 0 5px;
    font-weight: bold;
    font-size: 16px;
    border-radius: 5px;
}

nav a:hover,
nav a:focus {
    background-color: #131313; /* Black highlight */
    color: #F5EFE7; /* Soft background color for contrast */
    transition: 0.3s ease;
}

/* Main Content */
main {
    background-color: #FFF8E7; /* Slightly lighter tone for readability */
    color: #131313; /* Black text */
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2); /* Soft shadow */
    margin: 20px auto;
    max-width: 900px;
    font-size: 18px;
    line-height: 1.6;
}

/* Sections */
section {
    background-color: #F5EFE7; /* Main soft beige background */
    color: #131313; /* Black text */
    padding: 15px;
    margin-bottom: 20px;
    border-radius: 8px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2); /* Elevated feel */
}

/* Buttons */
button {
    background-color: #131313; /* Black background */
    color: #F5EFE7; /* Soft background color for text */
    border: 2px solid #131313; /* Refined black border */
    padding: 10px 20px;
    font-size: 16px;
    font-weight: bold;
    border-radius: 5px;
    cursor: pointer;
    transition: 0.3s ease;
}

button:hover {
    background-color: #F5EFE7; /* Match body background */
    color: #131313; /* Black text for contrast */
}

/* Footer */
footer {
    background-color: #E6D5B8; /* Beige */
    color: #131313; /* Black text */
    text-align: center;
    padding: 15px 0;
    border-top: 3px solid #131313; /* Black border */
    font-size: 14px;
}

/* Code Blocks */
pre, code {
    background-color: #FFF8E7; /* Light background for contrast */
    color: #131313; /* Black text */
    padding: 10px;
    border-radius: 5px;
    overflow-x: auto;
}

/* Tables */
table {
    width: 100%;
    border-collapse: collapse;
    background-color: #F5EFE7; /* Match soft beige background */
    color: #131313; /* Black text */
}

table th, table td {
    border: 1px solid #131313; /* Black borders */
    padding: 10px;
    text-align: left;
}

table th {
    background-color: #E6D5B8; /* Light beige header */
}

table tr:hover {
    background-color: #E6D5B8; /* Add hover color for rows */
}

:root {
  	ic-brand-primary: #031273;
		ic-brand-global-nav-bgd: #031273;
		ic-brand-global-nav-logo-bgd: #031273;
}
